can_reach_target_country = {
	has_diplomatic_relevance = $TARGET_COUNTRY$
	OR = {
		has_strategic_land_adjacency = $TARGET_COUNTRY$
		AND = {
			has_port_country = yes
			carrying_capacity >= 25
			$TARGET_COUNTRY$ = { capital = { has_coastal_access = yes } }
			$TARGET_COUNTRY$ = {
				any_scope_state = {
					is_coastal = yes
				}
			}
		}
	}
}

can_be_reached_by_target_country = {
	has_diplomatic_relevance = $TARGET_COUNTRY$
	OR = {
		has_strategic_land_adjacency = $TARGET_COUNTRY$
		AND = {
			capital = { has_coastal_access = yes }
			$TARGET_COUNTRY$ = { has_port_country = yes }
			$TARGET_COUNTRY$ = { carrying_capacity >= 25 }
		}
	}
}

can_reach_target_state = {
	has_diplomatic_relevance = $TARGET_STATE$.owner
	OR = {
		has_strategic_land_adjacency = $TARGET_STATE$
		AND = {
			carrying_capacity >= 25
			has_port_country = yes
			$TARGET_STATE$ = { is_coastal = yes }
		}
	}
}

