# Declare an Interest
sg_declare_an_interest = {
	category = sgcat_tutorial

	unlocking_subgoals_any = {
		sg_increase_relations
	}

	on_start = {
		if = {
			limit = {
				any_rival_country = {
					ROOT = {
						NOT = {
							has_strategic_region_interest_tier = {
								strategic_region = prev.capital.region
								value >= 1
							}
						}
					}
				}
			}
			random_rival_country = {
				limit = {
					ROOT = {
						NOT = {
							has_strategic_region_interest_tier = {
								strategic_region = prev.capital.region
